public int findKthLargest(int[] nums, int k) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    for (int num : nums) {
        minHeap.offer(num);
        if (minHeap.size() > k) minHeap.poll();
    }
    return minHeap.peek();
}

public int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int num : nums) freq.merge(num, 1, Integer::sum);
    PriorityQueue<Map.Entry<Integer, Integer>> minHeap =
        new PriorityQueue<>((a, b) -> a.getValue() - b.getValue());
    for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
        minHeap.offer(e);
        if (minHeap.size() > k) minHeap.poll();
    }
    int[] result = new int[k];
    for (int i = k - 1; i >= 0; i--) result[i] = minHeap.poll().getKey();
    return result;
}

class MedianFinder {
    private PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
    private PriorityQueue<Integer> upper = new PriorityQueue<>();
    public void addNum(int num) {
        lower.offer(num);
        upper.offer(lower.poll());
        if (upper.size() > lower.size()) lower.offer(upper.poll());
    }
    public double findMedian() {
        if (lower.size() > upper.size()) return lower.peek();
        return (lower.peek() + upper.peek()) / 2.0;
    }
}

public ListNode mergeKLists(ListNode[] lists) {
    PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> a.val - b.val);
    for (ListNode node : lists) if (node != null) heap.offer(node);
    ListNode dummy = new ListNode(-1), tail = dummy;
    while (!heap.isEmpty()) {
        ListNode curr = heap.poll();
        tail.next = curr;
        tail = tail.next;
        if (curr.next != null) heap.offer(curr.next);
    }
    return dummy.next;
}

public String reorganizeString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) freq[c - 'a']++;
    PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> b[1] - a[1]);
    for (int i = 0; i < 26; i++) if (freq[i] > 0) maxHeap.offer(new int[]{i, freq[i]});
    StringBuilder sb = new StringBuilder();
    int[] prev = null;
    while (!maxHeap.isEmpty()) {
        int[] curr = maxHeap.poll();
        sb.append((char) ('a' + curr[0]));
        curr[1]--;
        if (prev != null && prev[1] > 0) maxHeap.offer(prev);
        prev = curr;
    }
    return sb.length() == s.length() ? sb.toString() : "";
}

public int minMeetingRooms(int[][] intervals) {
    if (intervals.length == 0) return 0;
    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
    PriorityQueue<Integer> endTimes = new PriorityQueue<>();
    for (int[] interval : intervals) {
        if (!endTimes.isEmpty() && endTimes.peek() <= interval[0]) {
            endTimes.poll();
        }
        endTimes.offer(interval[1]);
    }
    return endTimes.size();
}

public int swimInWater(int[][] grid) {
    int n = grid.length;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
    boolean[][] visited = new boolean[n][n];
    pq.offer(new int[]{grid[0][0], 0, 0});
    int[] dr = {0, 0, 1, -1}, dc = {1, -1, 0, 0};
    while (!pq.isEmpty()) {
        int[] curr = pq.poll();
        int t = curr[0], r = curr[1], c = curr[2];
        if (visited[r][c]) continue;
        visited[r][c] = true;
        if (r == n - 1 && c == n - 1) return t;
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                pq.offer(new int[]{Math.max(t, grid[nr][nc]), nr, nc});
            }
        }
    }
    return -1;
}

class LazyHeap {
    private PriorityQueue<Integer> heap = new PriorityQueue<>();
    private Map<Integer, Integer> pendingDeletes = new HashMap<>();
    private int size = 0;
    public void add(int val) {
        heap.offer(val);
        size++;
    }
    public void remove(int val) {
        pendingDeletes.merge(val, 1, Integer::sum);
        size--;
    }
    public int peek() {
        prune();
        return heap.peek();
    }
    private void prune() {
        while (!heap.isEmpty() && pendingDeletes.getOrDefault(heap.peek(), 0) > 0) {
            int top = heap.poll();
            if (pendingDeletes.merge(top, -1, Integer::sum) == 0) pendingDeletes.remove(top);
        }
    }
    public int size() { return size; }
}

public int connectSticks(int[] sticks) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    for (int s : sticks) minHeap.offer(s);
    int totalCost = 0;
    while (minHeap.size() > 1) {
        int first = minHeap.poll();
        int second = minHeap.poll();
        int cost = first + second;
        totalCost += cost;
        minHeap.offer(cost);
    }
    return totalCost;
}
